    "text": "B2: गोपाल\nC2: सागर भूसाल\nD2: विनु (विनु महादेव)\nE2: खडानन्द\nF2: श्रीधर\nG2: रामकृष्ण\nH2: नरहरी भूसाल\nI2: लिङ्सियाली\nH3: धर्मागत भूसाल\nI3: मुसु\nI4: जगै\nJ4: बेउलीवासे\nG5: कमला पति\nH5: पृथ्वी नारायण\nI5: राम शर्मा\nJ5: गुरूङ्दी\nI6: चक्रपाणी\nJ6: उरामका दोवाटे,नुवारे\nI7: घनलाल\nJ7: जोखे, थुम्के,कटहरे,जामुनडाडे\nI8: जनार्दन\nJ8: सिरवानी, तिनतले, वाउढुंगेका\nI9: हरिनारायण\nJ9: निःसन्तान\nF10: ज्ञानेन्द्र (गर्वु)\nG10: उराम पोखरेल, पिडीखोले, सिंगारकोशे, ढुंगेखर्के, ढुंगेघरे, बाझवारी, च्यूरी खर्क, रामीडाडा, पात्ले पोखरा, वायखोले, चिलिमे, पाल्पा र चापाकोटे\nC11: शकर भूसाल\nD11: स्यांजा स्यांजाको भञ्ज्याङ्र सिर्वानी तिर गएका\nC12: महादेव\nD12: विवाह पूर्व मृत्यू",
